-- Roles (NOLOGIN; granted to the application user by the operator)
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'hai_pipeline') THEN CREATE ROLE hai_pipeline NOLOGIN; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'hai_engine') THEN CREATE ROLE hai_engine NOLOGIN; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'hai_reviewer') THEN CREATE ROLE hai_reviewer NOLOGIN; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'hai_api') THEN CREATE ROLE hai_api NOLOGIN; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'hai_admin') THEN CREATE ROLE hai_admin NOLOGIN; END IF; END $$;

CREATE SCHEMA IF NOT EXISTS hai;
GRANT USAGE ON SCHEMA hai TO hai_pipeline, hai_engine, hai_reviewer, hai_api, hai_admin;

CREATE TABLE hai.schema_versions (
    singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton),
    ontology_version text NOT NULL,
    methodology_version text NOT NULL,
    manifest_hash text NOT NULL,
    applied_at timestamptz NOT NULL DEFAULT now()
);
INSERT INTO hai.schema_versions (ontology_version, methodology_version, manifest_hash) VALUES ('1.2.0', '2.0.0', 'a3acbe3c3f4a52ab327d617285859022a3e54fd1e9c128f0f29d9a0a802d60df');
GRANT SELECT ON hai.schema_versions TO hai_pipeline, hai_engine, hai_reviewer, hai_api, hai_admin;

CREATE OR REPLACE FUNCTION hai.refuse_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'HAI_APPEND_ONLY: % is insert-only (IC-02)', TG_TABLE_NAME
        USING ERRCODE = 'integrity_constraint_violation';
END $$;

-- Enums: one per vocabulary
CREATE TYPE hai.admissibility AS ENUM ('admissible', 'pending_review', 'inadmissible_irrelevant', 'inadmissible_stale', 'inadmissible_unverifiable', 'inadmissible_untrusted');
CREATE TYPE hai.applicability_effect AS ENUM ('not_applicable', 'review');
CREATE TYPE hai.autonomy_level AS ENUM ('assistive', 'supervised', 'bounded_autonomous', 'open_autonomous');
CREATE TYPE hai.certification_outcome AS ENUM ('certified', 'not_certified', 'revoked');
CREATE TYPE hai.claim_scope_type AS ENUM ('organization', 'ai_system', 'control', 'incident', 'impact_measure');
CREATE TYPE hai.cluster_method AS ENUM ('exact_hash', 'simhash', 'manual');
CREATE TYPE hai.connector_run_outcome AS ENUM ('invoked', 'succeeded', 'blocked', 'failed', 'rate_limited');
CREATE TYPE hai.connector_status AS ENUM ('configured', 'active', 'retired');
CREATE TYPE hai.containment_threat AS ENUM ('restriction_bypass', 'unauthorized_access', 'privilege_escalation', 'safeguard_disablement', 'data_exfiltration', 'boundary_violation');
CREATE TYPE hai.content_status AS ENUM ('draft', 'approved');
CREATE TYPE hai.control_capability AS ENUM ('pause', 'shutdown', 'rollback', 'override', 'isolate', 'rate_limit');
CREATE TYPE hai.control_operational_status AS ENUM ('planned', 'implemented', 'operating', 'suspended', 'retired', 'unknown');
CREATE TYPE hai.coverage_state AS ENUM ('observed', 'missing', 'unavailable', 'not_applicable', 'not_tested', 'failed', 'contradictory');
CREATE TYPE hai.criterion_code AS ENUM ('TRU-01', 'TRU-02', 'TRU-03', 'TRU-04', 'ACC-01', 'ACC-02', 'ACC-03', 'PUR-01', 'PUR-02', 'PUR-03', 'SAF-01', 'SAF-02', 'SAF-03', 'TRN-01', 'TRN-02', 'TRN-03', 'IMP-01', 'IMP-02', 'IMP-03', 'IMP-04');
CREATE TYPE hai.criticality AS ENUM ('low', 'moderate', 'high', 'critical');
CREATE TYPE hai.evidence_class AS ENUM ('foundational_governance', 'core_governance', 'operational_evidence', 'external_validation');
CREATE TYPE hai.execution_level AS ENUM ('none', 'asserted', 'partial', 'verified');
CREATE TYPE hai.finding_validation_status AS ENUM ('accepted', 'rejected');
CREATE TYPE hai.focus_area AS ENUM ('control_verification', 'autonomous_monitoring', 'containment_security', 'evidence_basis', 'incident_response', 'independent_auditability', 'human_benefit');
CREATE TYPE hai.impact_evidence_kind AS ENUM ('stated_intention', 'output_metric', 'outcome_metric', 'independently_evaluated');
CREATE TYPE hai.incident_severity AS ENUM ('low', 'moderate', 'high', 'critical');
CREATE TYPE hai.incident_status AS ENUM ('alleged', 'under_investigation', 'substantiated', 'remediating', 'closed_verified', 'dismissed');
CREATE TYPE hai.independence AS ENUM ('self', 'affiliate', 'commissioned', 'independent', 'regulator');
CREATE TYPE hai.industry AS ENUM ('education', 'energy', 'financial_services', 'government', 'healthcare', 'hospitality', 'manufacturing', 'professional_services', 'retail', 'technology', 'travel', 'other');
CREATE TYPE hai.lifecycle_state AS ENUM ('queued', 'acquiring', 'evaluating', 'awaiting_review', 'completed_unverified', 'completed', 'failed', 'cancelled');
CREATE TYPE hai.materiality AS ENUM ('standard', 'high');
CREATE TYPE hai.maturity_rung AS ENUM ('none', 'stated_commitment', 'specified_control', 'documented_execution', 'independently_verified');
CREATE TYPE hai.maturity_status AS ENUM ('needs_attention', 'developing', 'progressing', 'strong');
CREATE TYPE hai.methodology_status AS ENUM ('draft', 'approved', 'retired');
CREATE TYPE hai.observability AS ENUM ('self_explanation', 'operator_logs', 'independent_recording');
CREATE TYPE hai.org_relation_type AS ENUM ('subsidiary', 'affiliate', 'acquired');
CREATE TYPE hai.outcome_status AS ENUM ('access_limited', 'insufficient_evidence', 'governance_baseline', 'confidence_too_low', 'certification_not_yet_achieved', 'hai_certified');
CREATE TYPE hai.pillar_code AS ENUM ('TRU', 'ACC', 'PUR', 'SAF', 'TRN', 'IMP');
CREATE TYPE hai.polarity AS ENUM ('supports', 'contradicts', 'neutral');
CREATE TYPE hai.publisher_type AS ENUM ('regulator_record', 'standards_registry', 'independent_audit', 'academic_research', 'press', 'org_disclosure', 'org_repository', 'archive', 'aggregator_or_social');
CREATE TYPE hai.review_action AS ENUM ('approve', 'reject', 'escalate', 'dismiss', 'substantiate', 'sign');
CREATE TYPE hai.review_subject_type AS ENUM ('incident', 'contradiction', 'confidence', 'finding', 'link', 'certification', 'appeal', 'applicability');
CREATE TYPE hai.rule_kind AS ENUM ('cap', 'gate', 'confidence', 'adjustment');
CREATE TYPE hai.rule_scope AS ENUM ('criterion', 'assessment');
CREATE TYPE hai.size_band AS ENUM ('small', 'mid', 'large', 'enterprise');
CREATE TYPE hai.source_tier AS ENUM ('T4', 'T3', 'T2', 'T1');
CREATE TYPE hai.stage_band AS ENUM ('early', 'growth', 'mature');
CREATE TYPE hai.target_type AS ENUM ('organization', 'ai_system', 'claim', 'control', 'test_outcome', 'incident', 'impact_measure');
CREATE TYPE hai.test_result AS ENUM ('pass', 'fail', 'inconclusive');
CREATE TYPE hai.verification_method AS ENUM ('document_review', 'tabletop_exercise', 'simulated_test', 'live_drill', 'red_team', 'independent_audit');

-- Tables

CREATE TABLE hai.audit_events (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    seq bigint NOT NULL UNIQUE,
    actor text NOT NULL,
    action text NOT NULL,
    subject_type text NOT NULL,
    subject_id uuid,
    before jsonb,
    after jsonb,
    reason text,
    at timestamptz NOT NULL,
    prev_hash text NOT NULL,
    hash text NOT NULL UNIQUE
);

CREATE TABLE hai.connectors (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    code text NOT NULL UNIQUE,
    name text NOT NULL,
    access_terms text,
    status hai.connector_status NOT NULL DEFAULT 'configured'
);

CREATE TABLE hai.methodology_versions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    semver text NOT NULL UNIQUE,
    effective_from date,
    approved_by text,
    change_record_uri text,
    status hai.methodology_status NOT NULL DEFAULT 'draft',
    manifest_hash text NOT NULL
);

CREATE TABLE hai.organizations (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    legal_name text NOT NULL,
    display_name text NOT NULL,
    primary_domain text NOT NULL UNIQUE,
    aliases text[],
    cik text,
    lei text,
    wikidata_qid text,
    github_handle text,
    industry_code text,
    stage_band hai.stage_band,
    size_band hai.size_band,
    jurisdictions text[],
    entity_confidence numeric,
    identifiers_verified boolean DEFAULT false,
    resolved_at timestamptz,
    CONSTRAINT ck_organizations_entity_confidence_range CHECK (entity_confidence IS NULL OR (entity_confidence >= 0 AND entity_confidence <= 1))
);

CREATE TABLE hai.rules (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    ruleset_version text NOT NULL,
    code text NOT NULL,
    kind hai.rule_kind NOT NULL,
    scope hai.rule_scope NOT NULL,
    run_order integer NOT NULL,
    expression_ref text NOT NULL,
    parameters jsonb,
    description text,
    CONSTRAINT uq_rules_ruleset_version_code UNIQUE (ruleset_version, code)
);

CREATE TABLE hai.source_clusters (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    cluster_key text NOT NULL UNIQUE,
    method hai.cluster_method NOT NULL,
    simhash text
);

CREATE TABLE hai.ai_systems (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    owner_org_id uuid NOT NULL,
    name text NOT NULL,
    use_case text,
    deployment_context text,
    criticality hai.criticality,
    autonomy_level hai.autonomy_level,
    monitoring_mode hai.observability,
    valid_from date,
    valid_to date
);

CREATE TABLE hai.assessments (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    org_id uuid NOT NULL,
    parent_assessment_id uuid,
    requested_by text NOT NULL,
    submitted_domain text NOT NULL,
    direct_urls text[],
    stage_band hai.stage_band NOT NULL,
    size_band hai.size_band NOT NULL,
    methodology_version text NOT NULL,
    ruleset_version text NOT NULL,
    prompt_version text NOT NULL,
    model_id text NOT NULL,
    lifecycle_state hai.lifecycle_state NOT NULL DEFAULT 'queued',
    idempotency_key text UNIQUE,
    certification_requested boolean NOT NULL DEFAULT false,
    failure_reason text,
    started_at timestamptz,
    finished_at timestamptz
);

CREATE TABLE hai.organization_relations (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    parent_org_id uuid NOT NULL,
    child_org_id uuid NOT NULL,
    relation_type hai.org_relation_type NOT NULL,
    valid_from date,
    valid_to date,
    CONSTRAINT ck_organization_relations_ck_orgrel_distinct CHECK (parent_org_id <> child_org_id)
);

CREATE TABLE hai.pillars (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    methodology_version_id uuid NOT NULL,
    code hai.pillar_code NOT NULL,
    name text NOT NULL,
    display_order integer NOT NULL,
    weight numeric NOT NULL,
    CONSTRAINT ck_pillars_weight_range CHECK (weight IS NULL OR (weight >= 0 AND weight <= 1)),
    CONSTRAINT uq_pillars_methodology_version_id_code UNIQUE (methodology_version_id, code)
);

CREATE TABLE hai.publishers (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    name text NOT NULL,
    domain text NOT NULL UNIQUE,
    publisher_type hai.publisher_type NOT NULL,
    org_id uuid
);

CREATE TABLE hai.assessment_results (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    assessment_id uuid NOT NULL,
    hai_score numeric,
    confidence_pct numeric,
    effectiveness numeric,
    score_before_caps numeric,
    caps_applied text[],
    outcome_status hai.outcome_status NOT NULL,
    gate_reasons text[],
    review_triggers text[],
    ruleset_version text NOT NULL,
    result_sha256 text NOT NULL,
    trace jsonb,
    supersedes_id uuid,
    CONSTRAINT ck_assessment_results_hai_score_range CHECK (hai_score IS NULL OR (hai_score >= 0 AND hai_score <= 100)),
    CONSTRAINT ck_assessment_results_confidence_pct_range CHECK (confidence_pct IS NULL OR (confidence_pct >= 0 AND confidence_pct <= 100)),
    CONSTRAINT ck_assessment_results_effectiveness_range CHECK (effectiveness IS NULL OR (effectiveness >= 0 AND effectiveness <= 100)),
    CONSTRAINT ck_assessment_results_score_before_caps_range CHECK (score_before_caps IS NULL OR (score_before_caps >= 0 AND score_before_caps <= 100))
);

CREATE TABLE hai.connector_runs (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    assessment_id uuid NOT NULL,
    connector_id uuid NOT NULL,
    outcome hai.connector_run_outcome NOT NULL DEFAULT 'invoked',
    error_code text,
    items_returned integer NOT NULL DEFAULT 0,
    started_at timestamptz NOT NULL,
    finished_at timestamptz,
    notes text,
    CONSTRAINT ck_connector_runs_items_returned_range CHECK (items_returned IS NULL OR (items_returned >= 0))
);

CREATE TABLE hai.controls (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    org_id uuid NOT NULL,
    ai_system_id uuid,
    name text NOT NULL,
    intended_risk text,
    owner_role text,
    threshold text,
    monitoring text,
    can_pause_or_rollback boolean,
    capabilities hai.control_capability[],
    monitoring_mode hai.observability,
    last_exercised_at date,
    operational_status hai.control_operational_status NOT NULL DEFAULT 'unknown',
    valid_from date,
    valid_to date
);

CREATE TABLE hai.criteria (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    methodology_version_id uuid NOT NULL,
    pillar_id uuid NOT NULL,
    code hai.criterion_code NOT NULL,
    pillar_code hai.pillar_code NOT NULL,
    name text NOT NULL,
    definition text NOT NULL,
    legacy_id text,
    content_status hai.content_status NOT NULL DEFAULT 'draft',
    materiality hai.materiality NOT NULL,
    materiality_weight numeric NOT NULL,
    weight numeric NOT NULL,
    freshness_window_months integer NOT NULL,
    CONSTRAINT ck_criteria_materiality_weight_range CHECK (materiality_weight IS NULL OR (materiality_weight >= 0)),
    CONSTRAINT ck_criteria_weight_range CHECK (weight IS NULL OR (weight >= 0)),
    CONSTRAINT ck_criteria_freshness_window_months_range CHECK (freshness_window_months IS NULL OR (freshness_window_months >= 1)),
    CONSTRAINT uq_criteria_methodology_version_id_code UNIQUE (methodology_version_id, code)
);

CREATE TABLE hai.criterion_findings (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    assessment_id uuid NOT NULL,
    criterion_code hai.criterion_code NOT NULL,
    proposed_level integer NOT NULL,
    evidence_link_ids uuid[] NOT NULL,
    contradicting_link_ids uuid[],
    uncertainty numeric NOT NULL,
    reasoning_summary text NOT NULL,
    provider text NOT NULL,
    model_id text NOT NULL,
    prompt_version text NOT NULL,
    attempt integer NOT NULL DEFAULT 1,
    validation_status hai.finding_validation_status NOT NULL,
    validation_errors jsonb,
    raw_output jsonb,
    role text NOT NULL DEFAULT 'primary',
    CONSTRAINT ck_criterion_findings_proposed_level_range CHECK (proposed_level IS NULL OR (proposed_level >= 1 AND proposed_level <= 5)),
    CONSTRAINT ck_criterion_findings_uncertainty_range CHECK (uncertainty IS NULL OR (uncertainty >= 0 AND uncertainty <= 1)),
    CONSTRAINT ck_criterion_findings_attempt_range CHECK (attempt IS NULL OR (attempt >= 1))
);

CREATE TABLE hai.evidence_snapshots (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    assessment_id uuid NOT NULL UNIQUE,
    frozen_at timestamptz NOT NULL,
    manifest_hash text NOT NULL,
    span_ids uuid[] NOT NULL,
    link_ids uuid[] NOT NULL,
    link_states jsonb NOT NULL,
    incident_states jsonb NOT NULL,
    target_states jsonb,
    connector_runs jsonb NOT NULL,
    version_pins jsonb NOT NULL,
    snapshot_sha256 text NOT NULL
);

CREATE TABLE hai.incidents (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    canonical_event_key text NOT NULL UNIQUE,
    org_id uuid NOT NULL,
    ai_system_id uuid,
    title text NOT NULL,
    summary text,
    occurred_at date,
    severity hai.incident_severity NOT NULL,
    status hai.incident_status NOT NULL DEFAULT 'alleged',
    affected_control_ids uuid[],
    most_material_criterion hai.criterion_code,
    containment_threat hai.containment_threat,
    detected_at date,
    disclosed_at date,
    contained_at date,
    corrected_at date,
    correction_verified_at date,
    correction_verified_by_org_id uuid,
    CONSTRAINT ck_incidents_ic_19 CHECK (correction_verified_at IS NULL OR correction_verified_by_org_id IS NOT NULL)
);

CREATE TABLE hai.pillar_scores (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    status hai.maturity_status,
    assessment_id uuid NOT NULL,
    pillar_code hai.pillar_code NOT NULL,
    score numeric NOT NULL,
    confidence numeric NOT NULL,
    criteria_counted integer NOT NULL,
    criteria_excluded integer NOT NULL,
    supersedes_id uuid,
    CONSTRAINT ck_pillar_scores_score_range CHECK (score IS NULL OR (score >= 0 AND score <= 100)),
    CONSTRAINT ck_pillar_scores_confidence_range CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 100)),
    CONSTRAINT ck_pillar_scores_criteria_counted_range CHECK (criteria_counted IS NULL OR (criteria_counted >= 0)),
    CONSTRAINT ck_pillar_scores_criteria_excluded_range CHECK (criteria_excluded IS NULL OR (criteria_excluded >= 0))
);

CREATE TABLE hai.reviews (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    subject_type hai.review_subject_type NOT NULL,
    subject_id uuid NOT NULL,
    assessment_id uuid,
    reviewer_id text NOT NULL,
    action hai.review_action NOT NULL,
    reason text NOT NULL,
    decided_at timestamptz NOT NULL,
    CONSTRAINT ck_reviews_ck_review_reason CHECK (length(btrim(reason)) > 0)
);

CREATE TABLE hai.certification_decisions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    assessment_id uuid NOT NULL,
    result_id uuid NOT NULL,
    threshold_applied numeric NOT NULL,
    decision hai.certification_outcome NOT NULL,
    gate_reasons text[],
    reviewer_id text NOT NULL,
    signed_at timestamptz NOT NULL,
    expires_at timestamptz,
    certificate_number text UNIQUE,
    signature text NOT NULL,
    supersedes_id uuid,
    CONSTRAINT ck_certification_decisions_ck_cert_reviewer CHECK (length(btrim(reviewer_id)) > 0)
);

CREATE TABLE hai.criterion_applicability (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    criterion_id uuid NOT NULL,
    condition text NOT NULL,
    effect hai.applicability_effect NOT NULL
);

CREATE TABLE hai.criterion_decisions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    assessment_id uuid NOT NULL,
    criterion_code hai.criterion_code NOT NULL,
    level integer,
    coverage_state hai.coverage_state NOT NULL,
    confidence numeric NOT NULL,
    applied_rule_codes text[] NOT NULL,
    finding_id uuid,
    trace jsonb NOT NULL,
    review_required boolean NOT NULL DEFAULT false,
    supersedes_id uuid,
    CONSTRAINT ck_criterion_decisions_ic_14 CHECK (cardinality(applied_rule_codes) >= 1),
    CONSTRAINT ck_criterion_decisions_ck_decision_level CHECK ((coverage_state IN ('unavailable', 'not_applicable') AND level IS NULL) OR (coverage_state NOT IN ('unavailable', 'not_applicable') AND level IS NOT NULL)),
    CONSTRAINT ck_criterion_decisions_level_range CHECK (level IS NULL OR (level >= 1 AND level <= 5)),
    CONSTRAINT ck_criterion_decisions_confidence_range CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 100))
);

CREATE TABLE hai.level_descriptors (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    criterion_id uuid NOT NULL,
    level integer NOT NULL,
    descriptor text NOT NULL,
    required_maturity_rung hai.maturity_rung NOT NULL,
    CONSTRAINT ck_level_descriptors_level_range CHECK (level IS NULL OR (level >= 1 AND level <= 5)),
    CONSTRAINT uq_level_descriptors_criterion_id_level UNIQUE (criterion_id, level)
);

CREATE TABLE hai.remediations (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    incident_id uuid NOT NULL,
    action text NOT NULL,
    committed_at date,
    completed_at date,
    verified_by_org_id uuid
