CREATE TABLE hai.source_documents (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    canonical_url text NOT NULL,
    publisher_id uuid NOT NULL,
    connector_run_id uuid NOT NULL,
    cluster_id uuid,
    title text,
    content_type text,
    language text,
    published_at date,
    retrieved_at timestamptz NOT NULL,
    sha256 text NOT NULL,
    text_sha256 text NOT NULL,
    snapshot_uri text NOT NULL,
    text_uri text NOT NULL,
    extraction_version text NOT NULL,
    rights text,
    valid_from date,
    valid_to date,
    supersedes_id uuid,
    CONSTRAINT uq_source_documents_canonical_url_sha256_connector_run_id UNIQUE (canonical_url, sha256, connector_run_id)
);

CREATE TABLE hai.test_outcomes (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    control_id uuid NOT NULL,
    protocol text,
    method hai.verification_method,
    capabilities_exercised hai.control_capability[],
    threats_exercised hai.containment_threat[],
    performed_at date NOT NULL,
    result hai.test_result NOT NULL,
    measured_value text,
    assessor_org_id uuid,
    verifier_org_id uuid
);

CREATE TABLE hai.claims (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    claimant_org_id uuid NOT NULL,
    assertion_text text NOT NULL,
    scope_type hai.claim_scope_type NOT NULL,
    scope_id uuid,
    claimed_at date,
    source_document_id uuid,
    verified_by_org_id uuid
);

CREATE TABLE hai.evidence_spans (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    source_document_id uuid NOT NULL,
    char_start integer NOT NULL,
    char_end integer NOT NULL,
    quote text NOT NULL,
    extracted_assertion text,
    asserted_dates date[],
    section_heading text,
    supersedes_id uuid,
    CONSTRAINT ck_evidence_spans_ck_span_range CHECK (char_end > char_start),
    CONSTRAINT ck_evidence_spans_ck_span_quote CHECK (length(btrim(quote)) > 0),
    CONSTRAINT ck_evidence_spans_char_start_range CHECK (char_start IS NULL OR (char_start >= 0)),
    CONSTRAINT ck_evidence_spans_char_end_range CHECK (char_end IS NULL OR (char_end >= 1))
);

CREATE TABLE hai.impact_measures (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    org_id uuid NOT NULL,
    ai_system_id uuid,
    kind hai.impact_evidence_kind NOT NULL DEFAULT 'stated_intention',
    outcome text NOT NULL,
    metric text,
    unit text,
    baseline_value numeric,
    measured_value numeric,
    population text,
    measured_at date,
    period_months integer,
    measured_by_org_id uuid,
    verifier_org_id uuid,
    source_document_id uuid,
    CONSTRAINT ck_impact_measures_ck_impact_verifier CHECK (kind <> 'independently_evaluated' OR verifier_org_id IS NOT NULL),
    CONSTRAINT ck_impact_measures_period_months_range CHECK (period_months IS NULL OR (period_months >= 1))
);

CREATE TABLE hai.evidence_links (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    span_id uuid NOT NULL,
    target_type hai.target_type NOT NULL,
    target_id uuid NOT NULL,
    criterion_code hai.criterion_code NOT NULL,
    polarity hai.polarity NOT NULL,
    admissibility hai.admissibility NOT NULL,
    admissibility_reason text,
    maturity_rung hai.maturity_rung NOT NULL DEFAULT 'none',
    execution_level hai.execution_level NOT NULL DEFAULT 'none',
    evidence_class hai.evidence_class NOT NULL,
    independence hai.independence NOT NULL,
    source_tier hai.source_tier NOT NULL,
    focus_area hai.focus_area,
    proposer text NOT NULL,
    relevance numeric,
    valid_from date,
    valid_to date,
    reviewer_id text,
    supersedes_id uuid,
    CONSTRAINT ck_evidence_links_ic_07 CHECK (maturity_rung <> 'independently_verified' OR independence IN ('independent', 'regulator')),
    CONSTRAINT ck_evidence_links_relevance_range CHECK (relevance IS NULL OR (relevance >= 0 AND relevance <= 1))
);

