-- Triggers: append-only tables, immutable columns, legal transitions
CREATE OR REPLACE TRIGGER trg_audit_events_append_only BEFORE UPDATE OR DELETE ON hai.audit_events
    FOR EACH ROW EXECUTE FUNCTION hai.refuse_change();
CREATE OR REPLACE FUNCTION hai.trgfn_assessments_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.org_id IS DISTINCT FROM OLD.org_id OR NEW.methodology_version IS DISTINCT FROM OLD.methodology_version OR NEW.ruleset_version IS DISTINCT FROM OLD.ruleset_version OR NEW.prompt_version IS DISTINCT FROM OLD.prompt_version OR NEW.model_id IS DISTINCT FROM OLD.model_id THEN
        RAISE EXCEPTION 'HAI_IMMUTABLE: assessments columns org_id, methodology_version, ruleset_version, prompt_version, model_id cannot change'
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER trg_assessments_immutable BEFORE UPDATE ON hai.assessments
    FOR EACH ROW EXECUTE FUNCTION hai.trgfn_assessments_immutable();
CREATE OR REPLACE FUNCTION hai.trgfn_assessments_lifecycle_state_transition() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.lifecycle_state IS DISTINCT FROM OLD.lifecycle_state AND NOT EXISTS (
        SELECT 1 FROM (VALUES
            ('queued', 'acquiring'),
            ('queued', 'cancelled'),
            ('acquiring', 'evaluating'),
            ('acquiring', 'failed'),
            ('acquiring', 'cancelled'),
            ('evaluating', 'awaiting_review'),
            ('evaluating', 'completed_unverified'),
            ('evaluating', 'failed'),
            ('awaiting_review', 'completed'),
            ('awaiting_review', 'completed_unverified'),
            ('completed_unverified', 'awaiting_review')
        ) AS t(src, dst)
        WHERE t.src = OLD.lifecycle_state::text AND t.dst = NEW.lifecycle_state::text
    ) THEN
        RAISE EXCEPTION 'HAI_TRANSITION: assessments.lifecycle_state cannot move from % to %', OLD.lifecycle_state, NEW.lifecycle_state
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER trg_assessments_lifecycle_state_transition BEFORE UPDATE OF lifecycle_state ON hai.assessments
    FOR EACH ROW EXECUTE FUNCTION hai.trgfn_assessments_lifecycle_state_transition();
CREATE OR REPLACE TRIGGER trg_assessment_results_append_only BEFORE UPDATE OR DELETE ON hai.assessment_results
    FOR EACH ROW EXECUTE FUNCTION hai.refuse_change();
CREATE OR REPLACE FUNCTION hai.trgfn_connector_runs_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.assessment_id IS DISTINCT FROM OLD.assessment_id OR NEW.connector_id IS DISTINCT FROM OLD.connector_id OR NEW.started_at IS DISTINCT FROM OLD.started_at THEN
        RAISE EXCEPTION 'HAI_IMMUTABLE: connector_runs columns assessment_id, connector_id, started_at cannot change'
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER trg_connector_runs_immutable BEFORE UPDATE ON hai.connector_runs
    FOR EACH ROW EXECUTE FUNCTION hai.trgfn_connector_runs_immutable();
CREATE OR REPLACE TRIGGER trg_criterion_findings_append_only BEFORE UPDATE OR DELETE ON hai.criterion_findings
    FOR EACH ROW EXECUTE FUNCTION hai.refuse_change();
CREATE OR REPLACE TRIGGER trg_evidence_snapshots_append_only BEFORE UPDATE OR DELETE ON hai.evidence_snapshots
    FOR EACH ROW EXECUTE FUNCTION hai.refuse_change();
CREATE OR REPLACE FUNCTION hai.trgfn_incidents_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.canonical_event_key IS DISTINCT FROM OLD.canonical_event_key THEN
        RAISE EXCEPTION 'HAI_IMMUTABLE: incidents columns canonical_event_key cannot change'
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER trg_incidents_immutable BEFORE UPDATE ON hai.incidents
    FOR EACH ROW EXECUTE FUNCTION hai.trgfn_incidents_immutable();
CREATE OR REPLACE FUNCTION hai.trgfn_incidents_status_transition() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.status IS DISTINCT FROM OLD.status AND NOT EXISTS (
        SELECT 1 FROM (VALUES
            ('alleged', 'under_investigation'),
            ('alleged', 'substantiated'),
            ('alleged', 'dismissed'),
            ('under_investigation', 'substantiated'),
            ('under_investigation', 'dismissed'),
            ('substantiated', 'remediating'),
            ('substantiated', 'closed_verified'),
            ('substantiated', 'dismissed'),
            ('remediating', 'closed_verified'),
            ('remediating', 'dismissed')
        ) AS t(src, dst)
        WHERE t.src = OLD.status::text AND t.dst = NEW.status::text
    ) THEN
        RAISE EXCEPTION 'HAI_TRANSITION: incidents.status cannot move from % to %', OLD.status, NEW.status
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER trg_incidents_status_transition BEFORE UPDATE OF status ON hai.incidents
    FOR EACH ROW EXECUTE FUNCTION hai.trgfn_incidents_status_transition();
