CREATE OR REPLACE FUNCTION hai.trgfn_evidence_links_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.span_id IS DISTINCT FROM OLD.span_id OR NEW.target_type IS DISTINCT FROM OLD.target_type OR NEW.target_id IS DISTINCT FROM OLD.target_id OR NEW.criterion_code IS DISTINCT FROM OLD.criterion_code OR NEW.polarity IS DISTINCT FROM OLD.polarity THEN
        RAISE EXCEPTION 'HAI_IMMUTABLE: evidence_links columns span_id, target_type, target_id, criterion_code, polarity cannot change'
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER trg_evidence_links_immutable BEFORE UPDATE ON hai.evidence_links
    FOR EACH ROW EXECUTE FUNCTION hai.trgfn_evidence_links_immutable();

