COMMENT ON COLUMN hai.certification_decisions.assessment_id IS 'The assessment.';
COMMENT ON COLUMN hai.certification_decisions.result_id IS 'The result certified.';
COMMENT ON COLUMN hai.certification_decisions.threshold_applied IS 'Threshold in force.';
COMMENT ON COLUMN hai.certification_decisions.decision IS 'certified, not_certified or revoked.';
COMMENT ON COLUMN hai.certification_decisions.gate_reasons IS 'Reasons when not certified or revoked.';
COMMENT ON COLUMN hai.certification_decisions.reviewer_id IS 'Named reviewer.';
COMMENT ON COLUMN hai.certification_decisions.signed_at IS 'Signing time.';
COMMENT ON COLUMN hai.certification_decisions.expires_at IS 'Expiry for a certified decision.';
COMMENT ON COLUMN hai.certification_decisions.certificate_number IS 'Public certificate number.';
COMMENT ON COLUMN hai.certification_decisions.signature IS 'HMAC over assessment, result and reviewer.';
COMMENT ON COLUMN hai.certification_decisions.supersedes_id IS 'The row this one corrects or replaces.';
COMMENT ON TABLE hai.criterion_applicability IS 'When a criterion does not apply or must be reviewed (decision D5).';
COMMENT ON COLUMN hai.criterion_applicability.criterion_id IS 'Owning criterion.';
COMMENT ON COLUMN hai.criterion_applicability.condition IS 'Safe expression over assessment inputs.';
COMMENT ON COLUMN hai.criterion_applicability.effect IS 'not_applicable or review.';
