COMMENT ON COLUMN hai.criterion_decisions.assessment_id IS 'The assessment.';
COMMENT ON COLUMN hai.criterion_decisions.criterion_code IS 'The criterion.';
COMMENT ON COLUMN hai.criterion_decisions.level IS 'Decided level. Null when the criterion is excluded.';
COMMENT ON COLUMN hai.criterion_decisions.coverage_state IS 'Observed, missing, unavailable and so on.';
COMMENT ON COLUMN hai.criterion_decisions.confidence IS 'Criterion confidence.';
COMMENT ON COLUMN hai.criterion_decisions.applied_rule_codes IS 'Rules that ran, in order.';
COMMENT ON COLUMN hai.criterion_decisions.finding_id IS 'The accepted finding used, if any.';
COMMENT ON COLUMN hai.criterion_decisions.trace IS 'Per-rule before and after state with a note.';
COMMENT ON COLUMN hai.criterion_decisions.review_required IS 'Routed to review.';
COMMENT ON COLUMN hai.criterion_decisions.supersedes_id IS 'The row this one corrects or replaces.';
