COMMENT ON COLUMN hai.level_descriptors.level IS 'Level 1 to 5.';
COMMENT ON COLUMN hai.level_descriptors.descriptor IS 'Descriptor text.';
COMMENT ON COLUMN hai.level_descriptors.required_maturity_rung IS 'Minimum rung for this level.';
COMMENT ON TABLE hai.remediations IS 'An action taken to fix an incident. Closure counts as independently verified only with an independent verifier.';
COMMENT ON COLUMN hai.remediations.incident_id IS 'The incident being remediated.';
COMMENT ON COLUMN hai.remediations.action IS 'What was done.';
COMMENT ON COLUMN hai.remediations.committed_at IS 'When the remediation was committed to.';
COMMENT ON COLUMN hai.remediations.completed_at IS 'When it was completed.';
COMMENT ON COLUMN hai.remediations.verified_by_org_id IS 'Independent verifier, if any.';
COMMENT ON TABLE hai.source_documents IS 'A frozen copy of a fetched or uploaded document with its hash, dates and rights. A re-fetch with a different hash is a new row.';
COMMENT ON COLUMN hai.source_documents.canonical_url IS 'Canonical URL after normalisation.';
COMMENT ON COLUMN hai.source_documents.publisher_id IS 'Who published it.';
COMMENT ON COLUMN hai.source_documents.connector_run_id IS 'The run that retrieved it.';
COMMENT ON COLUMN hai.source_documents.cluster_id IS 'Near-duplicate cluster, if any.';
COMMENT ON COLUMN hai.source_documents.title IS 'Document title.';
COMMENT ON COLUMN hai.source_documents.content_type IS 'MIME type of the raw bytes.';
COMMENT ON COLUMN hai.source_documents.language IS 'Detected language code.';
COMMENT ON COLUMN hai.source_documents.published_at IS 'Publication date asserted by the source.';
COMMENT ON COLUMN hai.source_documents.retrieved_at IS 'When Humaital fetched it.';
COMMENT ON COLUMN hai.source_documents.sha256 IS 'SHA-256 of the raw bytes.';
COMMENT ON COLUMN hai.source_documents.text_sha256 IS 'SHA-256 of the extracted text.';
COMMENT ON COLUMN hai.source_documents.snapshot_uri IS 'Blob store URI of the raw bytes.';
